import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class AllPairsShortestPaths {

    private final IntSquareMatrix distances;
    private final IntSquareMatrix nextHop;

    AllPairsShortestPaths(int[][] distances, int[][] nextHop) {
        this(IntSquareMatrix.from(distances), IntSquareMatrix.from(nextHop));
    }

    AllPairsShortestPaths(IntSquareMatrix distances, IntSquareMatrix nextHop) {
        this.distances = distances;
        this.nextHop = nextHop;
    }

    public int vertexCount() {
        return distances.size();
    }

    public IntSquareMatrix distances() {
        return distances;
    }

    public int distance(int source, int target) {
        return distances.get(source, target);
    }

    public List<Integer> path(int source, int target) {
        if (nextHop.get(source, target) == -1) {
            return Collections.emptyList();
        }

        List<Integer> path = new ArrayList<>();
        int current = source;
        path.add(current);

        while (current != target) {
            current = nextHop.get(current, target);
            if (current == -1) {
                return Collections.emptyList();
            }
            path.add(current);
        }

        return Collections.unmodifiableList(path);
    }

    public boolean isReachable(int source, int target) {
        return nextHop.get(source, target) != -1;
    }

    public boolean hasNegativeCycle() {
        for (int i = 0; i < distances.size(); i++) {
            if (distances.get(i, i) < 0) {
                return true;
            }
        }
        return false;
    }
}

public final class IntSquareMatrix {

    private final int[][] values;

    private IntSquareMatrix(int[][] values) {
        validateSquareMatrix(values);
        this.values = copyMatrix(values);
    }

    public static IntSquareMatrix from(int[][] values) {
        return new IntSquareMatrix(values);
    }

    public int size() {
        return values.length;
    }

    public int get(int row, int column) {
        validateIndex(row, values.length);
        validateIndex(column, values.length);
        return values[row][column];
    }

    public int[][] copyValues() {
        return copyMatrix(values);
    }

    public String toDisplayString() {
        StringBuilder builder = new StringBuilder();
        for (int i = 0; i < values.length; i++) {
            if (i > 0) {
                builder.append('\n');
            }

            for (int j = 0; j < values.length; j++) {
                if (j > 0) {
                    builder.append(' ');
                }
                builder.append(values[i][j]);
            }
        }
        return builder.toString();
    }

    @Override
    public String toString() {
        return toDisplayString();
    }

    private static void validateSquareMatrix(int[][] matrix) {
        if (matrix == null) {
            throw new IllegalArgumentException("Matrix must not be null.");
        }

        for (int i = 0; i < matrix.length; i++) {
            if (matrix[i] == null) {
                throw new IllegalArgumentException("Matrix row " + i + " must not be null.");
            }

            if (matrix[i].length != matrix.length) {
                throw new IllegalArgumentException("Matrix must be square.");
            }
        }
    }

    private static void validateIndex(int index, int size) {
        if (index < 0 || index >= size) {
            throw new IllegalArgumentException("Matrix index out of bounds: " + index);
        }
    }

    private static int[][] copyMatrix(int[][] source) {
        int[][] copy = new int[source.length][];
        for (int i = 0; i < source.length; i++) {
            copy[i] = source[i].clone();
        }
        return copy;
    }
}

public final class WeightedGraph {

    public static final int DEFAULT_UNREACHABLE_DISTANCE = 100_000_000;

    private final IntSquareMatrix adjacencyMatrix;
    private final int unreachableDistance;

    private WeightedGraph(int[][] adjacencyMatrix, int unreachableDistance) {
        this(IntSquareMatrix.from(adjacencyMatrix), unreachableDistance);
    }

    private WeightedGraph(IntSquareMatrix adjacencyMatrix, int unreachableDistance) {
        validateUnreachableDistance(unreachableDistance);

        this.adjacencyMatrix = adjacencyMatrix;
        this.unreachableDistance = unreachableDistance;
    }

    public static WeightedGraph from(int[][] adjacencyMatrix) {
        return new WeightedGraph(adjacencyMatrix, DEFAULT_UNREACHABLE_DISTANCE);
    }

    public static WeightedGraph from(int[][] adjacencyMatrix, int unreachableDistance) {
        return new WeightedGraph(adjacencyMatrix, unreachableDistance);
    }

    public int vertexCount() {
        return adjacencyMatrix.size();
    }

    public int unreachableDistance() {
        return unreachableDistance;
    }

    public int distance(int source, int target) {
        return adjacencyMatrix.get(source, target);
    }

    public boolean isUnreachable(int source, int target) {
        return distance(source, target) == unreachableDistance;
    }

    public IntSquareMatrix adjacencyMatrix() {
        return adjacencyMatrix;
    }

    private static void validateUnreachableDistance(int unreachableDistance) {
        if (unreachableDistance <= 0) {
            throw new IllegalArgumentException("Unreachable distance must be positive.");
        }
    }
}

